import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/movement/comparison'
def main():
 r=json.loads((OUT/'metrics.json').read_text());q=json.loads((OUT/'qwen-metadata.json').read_text());ds=json.loads((ROOT/'data/movement/dataset.json').read_text());inventory=json.loads((ROOT/'data/movement/inventory.json').read_text());p=r['protocol'];names={'numeric':'A 数字时序模型','qwen_adapter':'B Frozen Qwen + adapter','fusion':'C 融合模型','stationary':'不动','constant_velocity':'匀速','tuned_velocity':'验证集调优的衰减匀速'}
 lines=['# CS2 全地图 Frozen Qwen 三组对照实验报告','', '日期：2026-10-13。全部计算在本机执行，无付费模型调用。','', '## 结论','']
 a=r['overall']['numeric']['ADE'];b=r['overall']['qwen_adapter']['ADE'];c=r['overall']['fusion']['ADE'];base=r['overall']['tuned_velocity']['ADE']
 lines += [f'在本轮固定的测试集上，A/B/C 的平均位移误差（ADE，越低越好）分别为 **{a:.2f} / {b:.2f} / {c:.2f} 游戏单位**。较强的简单基准“衰减匀速”为 **{base:.2f}**。', '',f'融合相对数字模型的样本加权误差增加 **{(c-a)/a*100:.2f}%**；Frozen Qwen 单支增加 **{(b-a)/a*100:.2f}%**。数字模型相对衰减匀速基准降低误差 **{(base-a)/base*100:.2f}%**。','']
 ci=r['paired_series_improvement']['fusion_vs_numeric'];lo,hi=ci['ci95']
 lines += [f'以独立比赛为单位的配对比较：融合相对数字模型的平均 ADE 改善为 **{ci["mean"]:.2f}**，比赛 bootstrap 95% 区间 **[{lo:.2f}, {hi:.2f}]**。测试只有 {ci["series"]} 场，该区间仅是小样本探索性不确定性估计。', '', ('本轮方向上支持融合降低误差，但需要更多独立比赛复现，不能宣称已学会最优决策。' if lo>0 else '当前模板、池化、样本量与训练配置下，Qwen 单支和融合均未改善数字模型，融合在六场比赛上的配对区间也显示误差增加。应优先保留数字时序模型继续研究，不将这个结果外推为所有 LLM 方法无效。'), '', '本实验预测职业玩家真实后续位移，不判断该选择是否最优，也不模拟击杀、输赢或完整残局。','', '## 数据与划分','',f'- 原始目录：`C:/Users/zhiyu/Downloads/csdemo`。{len(inventory)} 个 RAR，经 SHA-256 去重后 {sum("demos" in x for x in inventory)} 个系列赛压缩包，{len(ds)} 份独立 demo；原文件未修改。',f'- 全量提取：{sum(x["rounds"] for x in ds):,} 个有效地图回合，{sum(x["samples"] for x in ds):,} 个合格玩家时间窗口，解析失败 {sum("error" in x for x in ds)} 份。',f'- 低成本首轮：每份 demo 固定随机抽取 64 个窗口，共 {r["samples"]:,} 个。所有 77 份录像和 7 张地图均参加实验；没有把全部 53.8 万窗口都送进 Qwen。',f'- 训练/验证/测试系列赛数：{r["split_series"]}；窗口数：{r["split_samples"]}。','- 三个集合均覆盖全部 7 张地图；同场系列赛所有地图同属一个集合，无跨集合 demo 哈希重复。','- 划分只依据比赛分组和地图覆盖，抽样只依据固定随机种子，不依据未来标签、胜负或模型结果。','- 这是未见比赛测试，不是未见地图测试，也不是普通玩家外部分布测试。部分原始比赛曾用于早期其他实验，因此不视为项目历史上完全未接触的数据。','', '## 输入、标签与模型','', '- 2 秒历史，0.5 秒采样；预测未来 0.5、1、2 秒的 XY 位移，坐标以当前玩家朝向旋转。','- 三组获得完全相同的输入数值，统一保留三位小数。Qwen 输入为固定模板、同样的历史和当前上下文；没有增加自然语言战术解释或额外检索。','- 输入：自身相对轨迹/高度、朝向变化、俯仰、蹲下、闪光状态；血甲、阵营、时间、双方存活人数、下包计时、最近两名队友的相对位置。','- 不含玩家身份、绝对地图坐标、隐藏敌方位置、未来事件、胜负或目标轨迹。队友位置及计数假定可从队伍雷达/记分板获得，未完整复现个人感知与通讯。','', '| 组别 | 实现 | 可训练参数 |','|---|---|---:|']
 for arm in ['numeric','qwen_adapter','fusion']:lines.append(f'| {names[arm]} | '+{'numeric':'48 维 GRU + 当前上下文 + 预测头','qwen_adapter':'冻结 Qwen3-4B，2560 维特征 → 64 维 adapter → 预测头','fusion':'GRU/上下文 + Qwen adapter，拼接后预测'}[arm]+f' | {r["fits"][arm][0]["parameters"]:,} |')
 lines += ['', '- Qwen 主干不更新；最后一层输出按有效 token 做均值池化；不生成回答。缓存只提取一次。','- 三组训练参数量不同，因此本实验是实用管线比较，不是等参数量的架构因果消融。',f'- 共同设置：3 个随机种子 {p["seeds"]}、最多 {p["epochs"]} epoch、batch={p["batch_size"]}、AdamW lr=0.001、weight_decay=0.01、梯度裁剪 5；loss 是三时点欧氏距离均值。','- Qwen 特征标准化只使用训练集统计；每个种子的最佳 epoch 只按验证 ADE 选；最终预测是三个种子的平均。测试结果未用于调参。','', '## 留出测试结果','', '误差单位为 CS2 游戏单位，越小越好。ADE 为三个时间点的平均误差；FDE 为 2 秒终点误差。','', '| 方法 | ADE | 0.5秒误差 | 1秒误差 | 2秒终点误差 |','|---|---:|---:|---:|---:|']
 for k in names:
  v=r['overall'][k];lines.append(f'| {names[k]} | {v["ADE"]:.2f} | {v["error_05s"]:.2f} | {v["error_1s"]:.2f} | {v["FDE_2s"]:.2f} |')
 lines += ['',f'衰减匀速系数 {r["tuned_velocity_factor"]:.2f} 由验证集选择。该基准比只对比“不动”更严格。','', '### 明显移动的窗口','', '筛选实际 2 秒终点距离超过 100 游戏单位的窗口，仅用于分组统计，不用于训练筛样。','', '| 方法 | 数量 | ADE | 2秒终点误差 |','|---|---:|---:|---:|']
 for k in names:
  v=r['moving_only'][k];lines.append(f'| {names[k]} | {v["n"]} | {v["ADE"]:.2f} | {v["FDE_2s"]:.2f} |')
 lines += ['', '### 每张地图的 ADE','', '| 地图 | 测试窗口 | A 数字 | B Qwen | C 融合 | 衰减匀速 |','|---|---:|---:|---:|---:|---:|']
 for m,v in r['by_map'].items():lines.append(f'| {m} | {v["numeric"]["n"]} | '+ ' | '.join(f'{v[k]["ADE"]:.2f}' for k in ['numeric','qwen_adapter','fusion','tuned_velocity'])+' |')
 lines += ['', '每图样本较少，来自少量系列赛，不能据此给地图排名。','', '### 种子稳定性与训练选择','', '| 组别 | seed | 最佳epoch | 验证ADE | 测试ADE | 训练秒 |','|---|---:|---:|---:|---:|---:|']
 for arm in ['numeric','qwen_adapter','fusion']:
  for v in r['fits'][arm]:lines.append(f'| {names[arm]} | {v["seed"]} | {v["best_epoch"]} | {v["validation_ADE"]:.2f} | {v["test"]["ADE"]:.2f} | {v["seconds"]:.1f} |')
 lines += ['', '### 比赛为单位的配对不确定性','', '正值表示前者比后者误差更低；比赛均等加权，所以不同于上面按样本数加权的总体 ADE。','', '| 对比 | 平均改善 | bootstrap 95%区间 |','|---|---:|---|']
 for k,v in r['paired_series_improvement'].items():lines.append(f'| {k} | {v["mean"]:.2f} | [{v["ci95"][0]:.2f}, {v["ci95"][1]:.2f}] |')
 lines += ['', '## 实测资源与成本','',f'- GPU：{r["gpu"]}。',f'- Qwen 特征提取：{q["seconds"]:.1f} 秒，峰值分配显存 {q["peak_gpu_mb"]:.0f} MiB；共 {q["total_tokens"]:,} token，单片段最多 {q["max_tokens"]} token，未截断。',f'- 九次小模型拟合及评估：{r["training_seconds"]:.1f} 秒，峰值分配显存 {r["training_peak_gpu_mb"]:.0f} MiB。','- 上述显存是 PyTorch 分配峰值，不是整机或其他进程总显存；训练时间不含原始录像解压/解析。','- 外部 API 调用 0 次；本地电耗未测量。','- 缓存特征后的单样本预测时间（单个 seed，预热后，不含 Qwen 前向和文本构造）：'+str({k:round(v,3) for k,v in r['cached_feature_single_sample_ms'].items()})+' 毫秒。不能将这一数字作为 Qwen 管线的端到端延迟。','', '## 局限和下一步','', '1. 目前没有地图几何/导航/视线、敌人可见性历史、真实烟雾和穿墙伤害输入。不能据此检验地图空间理解，更不能用它直接判断玩家失误。','2. 标签是职业玩家实际走法；一次观测不覆盖其他合理选择。回归输出还可能平均多条路线而穿墙。下一阶段需要多候选轨迹及地图可达性过滤。','3. 只保留整个历史和未来窗口均存活、没有异常位移的片段，存在生存者选择偏差，不覆盖死亡风险结局。','4. 64 窗口/demo 是计算预算取舍，数据规模远小于完整提取集；“全部地图一起训练”不代表已经使用每一帧。','5. 只测试单一文本模板、冻结模型和池化方式，不能把结果泛化为所有 frozen LLM 或 LoRA 方法的结论。','6. 后续应先在验证集加入更充分的时序/地形输入，并做参数量匹配对照；扩容或调整后必须另留新比赛作确认测试。当前测试集已经打开。','7. 本轮结果没有自动接入网站推荐或 AgentLoop，也没有替换现有功能。实验产物可供之后集成。','', '## 完整比赛清单','', '| 系列赛压缩包 | 划分 | 地图文件数 |','|---|---|---:|']
 for a in inventory:
  if 'demos' in a:lines.append(f'| {a["archive"]} | {p["split"][a["group"]]} | {len(a["demos"])} |')
 lines += ['', '重复压缩包：'+', '.join(x['archive']+' → '+x['duplicate_of'] for x in inventory if 'duplicate_of' in x),'', '## 可复现产物','', '- `protocol.json`：固定划分、采样和训练协议。','- `rows.json`、`data.npz`、`prompts.json`：样本身份、三组相同输入、Qwen 原始文本。','- `qwen-features.npy`、`qwen-metadata.json`：冻结特征及哈希、版本、时间。','- `embedding-scaler.npz`：只由训练集拟合的标准化统计。','- `numeric-*.pt`、`qwen_adapter-*.pt`、`fusion-*.pt`：九个 checkpoint。','- `metrics.json`、`test-predictions.npz`：详细指标和原始预测。','- `tests.log`：数据隔离、特征一致性、模型梯度与指标检查。','- 脚本位于 `experiments/movement/`，实验操作说明见 `COMPARISON.md`。','']
 (OUT/'全地图三组对照实验报告.md').write_text('\n'.join(lines),encoding='utf-8')
 print('\n'.join(lines[:14]))
if __name__=='__main__':main()
